 "rules": [
  {
   "id": "R-01",
   "label": "公共服务配套建筑面积换算",
   "expr": "公共服务配套建筑面积 = 公共服务配套使用面积需求 ÷ 综合平面利用系数",
   "inputs": [
    "公共服务配套使用面积需求",
    "综合平面利用系数"
   ],
   "output": "公共服务配套建筑面积需求",
   "anchor": "使用面积需求合计约1210平方米，按照0.55的综合平面利用系数换算为建筑面积需求为2200平方米"
  },
  {
   "id": "R-02",
   "label": "科研人员用房建筑面积",
   "expr": "科研人员用房建筑面积 = 科研人员规划数 × 16 ㎡/人",
   "inputs": [
    "科研人员规划数",
    "科研人员人均建筑面积指标上限"
   ],
   "output": "科研人员用房需求建筑面积",
   "anchor": "本项目科研用房人均建筑面积指标应不超过16㎡/人"
  },
  {
   "id": "R-03",
   "label": "研究生等用房建筑面积",
   "expr": "研究生、博士生、访问学者用房建筑面积 = 该类规划人数 × 8 ㎡/人",
   "inputs": [
    "研究生等规划数合计",
    "研究生等人均建筑面积指标上限"
   ],
   "output": "研究生等用房需求建筑面积",
   "anchor": "本项目科研用房人均建筑面积指标应不超过16㎡/人"
  },
  {
   "id": "R-04",
   "label": "地上建筑面积需求",
   "expr": "地上建筑面积需求 = 科研人员用房 + 研究生等用房 + 公共服务配套建筑面积",
   "inputs": [
    "科研人员用房需求建筑面积",
    "研究生等用房需求建筑面积",
    "公共服务配套建筑面积需求"
   ],
   "output": "地上建筑面积需求",
   "anchor": "本项目研究中心地上总建筑面积需求为315人×16㎡/人"
  },
  {
   "id": "R-05",
   "label": "项目总投资",
   "expr": "项目总投资 = 建筑安装工程费 + 工程建设其他费 + 基本预备费 + 拆除费",
   "inputs": [
    "建筑安装工程费用（估算表）",
    "工程建设其他费（估算表）",
    "基本预备费",
    "拆除费"
   ],
   "output": "项目总投资（估算表）",
   "anchor": "| 五 | 总计 | 18319 | ㎡ | 7114 | 13032 | （一+二+三+四） |"
  },
  {
   "id": "R-06",
   "label": "基本预备费",
   "expr": "基本预备费 = (建筑安装工程费 + 工程建设其他费) × 5%",
   "inputs": [
    "建筑安装工程费用（估算表）",
    "工程建设其他费（估算表）",
    "基本预备费率"
   ],
   "output": "基本预备费",
   "anchor": "| 三 | 基本预备费 | 18319 | ㎡ | 337 | 618 | （一+二）*5％ |"
  },
  {
   "id": "R-07",
   "label": "拆除费",
   "expr": "拆除费 = 拆除面积 × 拆除单价(200 元/㎡)",
   "inputs": [
    "拆除面积",
    "拆除单价"
   ],
   "output": "拆除费",
   "anchor": "| 四 | 拆除费 | 2758 | ㎡ | 200 | 55 | 拆除原老旧建筑 |"
  },
  {
   "id": "R-08",
   "label": "人防易地建设费",
   "expr": "人防易地建设费 = 地上建筑面积 × 60 元/㎡",
   "inputs": [
    "地上建筑面积",
    "人防易地建设费单价"
   ],
   "output": "人防易地建设费",
   "anchor": "| 12 | 人防易地建设费 | 18000 | ㎡ | 60 | 108 | 地上面积*60元/m2 |"
  },
  {
   "id": "R-09",
   "label": "勘察费",
   "expr": "勘察费 = 建筑安装工程费 × 0.35%",
   "inputs": [
    "建筑安装工程费用（估算表）",
    "勘察费率"
   ],
   "output": "勘察费",
   "anchor": "| 3 | 勘察费 |  |  |  | 39 | 建安费*0.35% |"
  },
  {
   "id": "R-10",
   "label": "竣工图编制费",
   "expr": "竣工图编制费 = 设计费 × 8%",
   "inputs": [
    "设计费"
   ],
   "output": "竣工图编制费",
   "anchor": "| 9 | 竣工图编制费 |  |  |  | 27 | 设计费×8% |"
  },
  {
   "id": "R-11",
   "label": "场地准备及临时设施费",
   "expr": "场地准备及临时设施费 = 建筑安装工程费 × 0.5%",
   "inputs": [
    "建筑安装工程费用（估算表）"
   ],
   "output": "场地准备及临时设施费",
   "anchor": "| 10 | 场地准备及临时设施费 |  |  |  | 56 | （一）*0.5% |"
  },
  {
   "id": "R-12",
   "label": "未预见水量",
   "expr": "未预见水量 = 各项用水量之和 × 10%",
   "inputs": [
    "教师日用水量",
    "学生日用水量"
   ],
   "output": "未预见水量",
   "anchor": "不可预计用水量按总用水量的10%计算"
  },
  {
   "id": "R-13",
   "label": "年用水量",
   "expr": "年用水量(万m³) = 日用水量(m³/d) × 用水天数(d) ÷ 10000",
   "inputs": [
    "教师日用水量",
