   "output": "年总用水量",
   "anchor": "| 1 | 教师用水 | 35 | L/人·d | 288 | 人 | 10.1 | 193 | 0.19 |"
  },
  {
   "id": "R-14",
   "label": "年用电量",
   "expr": "年用电量(万kWh) = 用电面积 × 用电指标 × 需要系数 × 同时使用系数 × 日均工作小时 × 年工作天数 ÷ 10000",
   "inputs": [
    "科研用房用电面积",
    "科研用房用电指标",
    "科研用房需要系数",
    "科研用房同时使用系数"
