   "output": "科研用房年用电量",
   "anchor": "| 1 | 科研用房 | 14883 | 60 | 0.8 | 0.6 | 8 | 193 | 66 |"
  },
  {
   "id": "R-15",
   "label": "折标煤",
   "expr": "折标煤(tce) = 能源消耗量 × 折标系数",
   "inputs": [
    "水折标系数",
    "电力折标系数（当量值）"
