  {
   "id": "R-16",
   "label": "单位面积综合能耗",
   "expr": "单位面积综合能耗(kgce/㎡) = 折标煤总量(tce) × 1000 ÷ 总建筑面积",
   "inputs": [
    "综合能耗（当量值）",
