  {
   "id": "R-19",
   "label": "热负荷",
   "expr": "热负荷(kW) = 建筑面积 × 单位面积热负荷指标(W/㎡) ÷ 1000",
   "inputs": [
    "总建筑面积",
    "单位面积热负荷指标"
